import{_ as n,C as s,o as t,c as l,a2 as a,b as o,w as i,a as d,E as c,a3 as p}from"./chunks/framework.Brv5O9VI.js";const _=JSON.parse('{"title":"14.9 Reliability, Resilience & Fault Tolerance","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.9-reliability-and-resilience.md","filePath":"system-design/14.9-reliability-and-resilience.md"}'),u={name:"system-design/14.9-reliability-and-resilience.md"};function h(g,e,f,m,y,b){const r=s("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="_14-9-reliability-resilience-fault-tolerance" tabindex="-1">14.9 Reliability, Resilience &amp; Fault Tolerance <a class="header-anchor" href="#_14-9-reliability-resilience-fault-tolerance" aria-label="Permalink to &quot;14.9 Reliability, Resilience &amp; Fault Tolerance&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Reliability is the ability of a system to remain continuously operational and return accurate, timely responses despite hardware crashes, unexpected software exceptions, network drops, or malicious inputs.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Input Validation Sanitization</strong>: Pydantic v2 schemas reject malformed inputs before reaching business logic ([<code>app.py:L61-L67</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L61-L67)).</li><li><strong>Liveness &amp; Health Probe</strong>: Dedicated <code>GET /</code> endpoint returning service status ([<code>app.py:L69-L71</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L69-L71)).</li><li><strong>Graceful Error Degradation</strong>: If Scikit-Learn predicts an unexpected label, it falls back gracefully to <code>&quot;General Compliance&quot;</code> ([<code>app.py:L86-L87</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L86-L87)); if a query fails domain guardrails, it returns a polite explanation rather than throwing an unhandled HTTP 500 error ([<code>app.py:L96-L99</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L96-L99)).</li><li><strong>Circuit Breakers / Retries</strong>: <strong>Not Used</strong>. The backend makes <strong>zero outbound network calls</strong>, meaning external network timeouts cannot occur.</li></ul>',6)),(t(),o(p,null,{default:i(()=>[c(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20ClientReq%5B%22Incoming%20Client%20Request%22%5D%20--%3E%20Validator%7B%22Pydantic%20Validation%20(app.py)%22%7D%0A%20%20%20%20Validator%20--%3E%7CMalformed%20%2F%20Missing%20Field%7C%20Err422%5B%22HTTP%20422%20Response%20(Safe%20Rejection)%22%5D%0A%20%20%20%20Validator%20--%3E%7CEmpty%20Query%20String%7C%20Err400%5B%22HTTP%20400%20'Empty%20query.'%22%5D%0A%20%20%20%20Validator%20--%3E%20Guardrail%7B%22Domain%20Guardrail%20Check%22%7D%0A%20%20%20%20Guardrail%20--%3E%7COut%20of%20Domain%7C%20SafeNarrative%5B%22HTTP%20200%20(Clean%20Rejection%2C%20audit_data%3Dnull)%22%5D%0A%20%20%20%20Guardrail%20--%3E%7CValid%20Standard%7C%20Audit%5B%22Compute%20Gap%20Analysis%20%26%20Return%20200%20OK%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-with-reliability-patterns" tabindex="-1">3. Comparison with Reliability Patterns <a class="header-anchor" href="#_3-comparison-with-reliability-patterns" aria-label="Permalink to &quot;3. Comparison with Reliability Patterns&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Pattern</th><th style="text-align:left;">Mechanism</th><th style="text-align:left;">Relevance to This Engine</th><th style="text-align:left;">Status in Codebase</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Defensive Input Validation</strong></td><td style="text-align:left;">Strict schema boundaries via Pydantic</td><td style="text-align:left;">Critical for web security</td><td style="text-align:left;"><strong>Implemented</strong> ([<code>app.py:L61</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L61))</td></tr><tr><td style="text-align:left;"><strong>Safe Fallbacks</strong></td><td style="text-align:left;">Defaulting unknown classes to safe strings</td><td style="text-align:left;">Prevents unhandled exceptions</td><td style="text-align:left;"><strong>Implemented</strong> ([<code>app.py:L87</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L87))</td></tr><tr><td style="text-align:left;"><strong>Health Probes</strong></td><td style="text-align:left;">Endpoint for orchestrator liveness checks</td><td style="text-align:left;">Critical for zero-downtime</td><td style="text-align:left;"><strong>Implemented</strong> ([<code>app.py:L69</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L69))</td></tr><tr><td style="text-align:left;"><strong>Circuit Breaker (Resilience4j/PyBreaker)</strong></td><td style="text-align:left;">Tripping requests to failing external APIs</td><td style="text-align:left;">N/A (Zero external network calls)</td><td style="text-align:left;">Not Applicable</td></tr><tr><td style="text-align:left;"><strong>Exponential Backoff Retries</strong></td><td style="text-align:left;">Retrying transient network failures</td><td style="text-align:left;">N/A (Local in-memory search)</td><td style="text-align:left;">Not Applicable</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>In-Memory Volatility</strong>: If the server process crashes due to an out-of-memory error, all active connections drop. This requires an external process supervisor (Docker or Kubernetes) with an automated restart policy (<code>restart: always</code>).</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Docker restart policies easily handle isolated process restarts within 1.5 seconds.</li><li><strong>At 100x Load</strong>: If multiple pods restart simultaneously during a deployment, request queues drop.</li><li><strong>At 1000x Load</strong>: Requires a multi-region deployment with global DNS failover (Route 53) to guarantee 99.99% availability (Four Nines).</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><ol><li>Configure <strong>Kubernetes Pod Disruption Budgets (PDB)</strong> ensuring at least 2 replica pods remain online during cluster upgrades.</li><li>Add structured exception handling middleware that catches unexpected runtime panics and returns standardized JSON error envelopes with tracking IDs.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Our architecture achieves high reliability because it makes zero outbound network calls, completely eliminating the cascading failures, timeouts, and circuit breaker requirements of cloud-dependent microservices. Input sanitization is strictly enforced by Pydantic, unclassified intents gracefully fall back to default compliance categories, and Kubernetes health probes monitor the service for automatic instant restarts.&quot;</p></blockquote>',15))])}const k=n(u,[["render",h]]);export{_ as __pageData,k as default};
